    jmp .flat_outer
.flat_done:
    mov rax, r13
    pop r14
    pop r13
    pop r12
    pop rbp
    ret

_nova_unique:
    push rbp
    mov rbp, rsp
    push r12
    push r13
    push r14
    push r15
    mov r12, rdi
    call _nova_list_new
    mov r13, rax
    xor r14d, r14d
.uniq_outer:
    cmp r14, [r12 + 8]
    jge .uniq_done
    mov rax, [r12 + 24]
    mov r15, [rax + r14*8]
    mov rdi, r13
    mov rsi, r15
    push r14
    call _nova_contains
    pop r14
    test rax, rax
    jnz .uniq_skip
    mov rdi, r13
    mov rsi, r15
    push r14
    call _nova_push
    pop r14
.uniq_skip:
    inc r14
    jmp .uniq_outer
.uniq_done:
    mov rax, r13
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbp
    ret

_nova_map_merge:
    push rbp
    mov rbp, rsp
    push r12
    push r13
    push r14
    push r15
    mov r12, rdi
    mov r13, rsi
    call _nova_map_new
    mov r14, rax
    mov r15, [r12 + 16]
    xor ecx, ecx
.mm_loop1:
    cmp rcx, r15
    jge .mm_phase2
    mov rax, [r12 + 24]
    imul rdi, rcx, 24
    add rdi, rax
    cmp qword ptr [rdi + 16], 0
    je .mm_skip1
    push rcx
    mov rsi, [rdi]
    mov rdx, [rdi + 8]
    mov rdi, r14
    call _nova_map_set
    pop rcx
.mm_skip1:
    inc rcx
    jmp .mm_loop1
.mm_phase2:
    mov r15, [r13 + 16]
    xor ecx, ecx
.mm_loop2:
    cmp rcx, r15
    jge .mm_done
    mov rax, [r13 + 24]
    imul rdi, rcx, 24
    add rdi, rax
    cmp qword ptr [rdi + 16], 0
    je .mm_skip2
    push rcx
    mov rsi, [rdi]
    mov rdx, [rdi + 8]
    mov rdi, r14
    call _nova_map_set
    pop rcx
.mm_skip2:
    inc rcx
    jmp .mm_loop2
.mm_done:
    mov rax, r14
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbp
    ret

