_nova_str_to_chars:
    push rbp
    mov rbp, rsp
    push r12
    push r13
    push r14
    sub rsp, 8
    mov r12, rdi
    xor r13, r13
.stc_len:
    movzx rax, byte ptr [r12 + r13]
    test al, al
    jz .stc_got_len
    inc r13
    jmp .stc_len
.stc_got_len:
    call _nova_list_new
    mov r14, rax
    xor r13, r13
.stc_loop:
    movzx rax, byte ptr [r12 + r13]
    test al, al
    jz .stc_done
    mov rdi, r14
    mov rsi, rax
    call _nova_push
    inc r13
    jmp .stc_loop
.stc_done:
    mov rax, r14
    add rsp, 8
    pop r14
    pop r13
    pop r12
    pop rbp
    ret

